import sys
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(HERE))

from agent_core import AgentController, ACCEPTANCE_REVIEW_SYSTEM_PROMPT


class AcceptanceFinalStateV0218Tests(unittest.TestCase):
    def test_evidence_is_scoped_to_claimed_final_file(self):
        final_files = {
            "a.php": "$status = 'alle';\n",
            "b.php": "$status = 'aktiv';\n",
        }
        checks, problems = AgentController._validate_acceptance_checks(
            [{
                "requirement": "b.php muss alle setzen.",
                "satisfied": True,
                "path": "b.php",
                "evidence": "$status = 'alle';",
                "reason": "Der Beleg darf nicht aus a.php stammen.",
            }],
            final_files,
        )
        self.assertEqual(checks, [])
        self.assertTrue(problems)

    def test_exact_current_file_snippet_is_accepted(self):
        final_files = {
            "nav/settings_benutzer.php": (
                '<input type="text" name="q" value="<?= ausgabe($suche ?? \'\') ?>">\n'
                '</div>\n'
                '<div class="formular__feld">\n'
                '<select id="status" name="status">\n'
            ),
        }
        checks, problems = AgentController._validate_acceptance_checks(
            [{
                "requirement": "Suchwert bleibt sichtbar.",
                "satisfied": True,
                "path": "nav/settings_benutzer.php",
                "evidence": '<input type="text" name="q" value="<?= ausgabe($suche ?? \'\') ?>">',
                "reason": "Der Input bindet den aktuellen Suchwert.",
            }],
            final_files,
        )
        self.assertEqual(problems, [])
        self.assertEqual(len(checks), 1)

    def test_final_file_prompt_exposes_unchanged_old_behavior(self):
        snapshot = AgentController._acceptance_final_files_prompt({
            "nav/settings_benutzer.php": (
                "<?php if ($benutzer_liste === []): ?>\n"
                "Noch keine Benutzer vorhanden.\n"
                "<?php endif; ?>\n"
            ),
        })
        self.assertIn("===== nav/settings_benutzer.php =====", snapshot)
        self.assertIn("Noch keine Benutzer vorhanden.", snapshot)
        self.assertIn(
            "Footer oder allgemeiner Filterhinweis reicht NICHT",
            ACCEPTANCE_REVIEW_SYSTEM_PROMPT,
        )

    def test_noncontiguous_synthetic_snippet_is_rejected(self):
        final_files = {
            "nav/settings_benutzer.php": (
                '<input name="q">\n'
                '</div>\n'
                '<div class="formular__feld">\n'
                '<select name="status">\n'
            ),
        }
        checks, problems = AgentController._validate_acceptance_checks(
            [{
                "requirement": "Aktuelle Werte bleiben sichtbar.",
                "satisfied": True,
                "path": "nav/settings_benutzer.php",
                "evidence": '<input name="q"> <select name="status">',
                "reason": "Getrennte Stellen dürfen nicht künstlich zusammengezogen werden.",
            }],
            final_files,
        )
        self.assertEqual(checks, [])
        self.assertTrue(problems)


if __name__ == "__main__":
    unittest.main()
